function make(domain, rows){
  return rows.map(([word,meaning,definition,example])=>({id:`${domain.toLowerCase().replace(/[^a-z0-9]+/g,'-')}-${word.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`,domain,word,meaning,definition,example}))
}
